SET
	USER_PW               = #{userPw}
	, PWD_CHG_DTIME       = NOW()
	, PWD_FAIL_CNT        = 0
	, PWD_LOCK_YN         = 'N'
	, PWD_LOCK_EXPIRE_DTIME = NULL
	, UPDATE_NO           = #{userCd}
	, UPDATE_DATE         = NOW()
WHERE 1=1
  AND CMPNY_CD = #{cmpnyCd}
  AND USER_CD  = #{userCd}

/* User01Mapper.scheduleWithdrawal */
UPDATE TB_USER
SET
	WITHDRAWAL_DATE = #{withdrawalDate}
	, UPDATE_NO     = #{gvUserCd}
	, UPDATE_DATE   = NOW()
WHERE 1=1
  AND CMPNY_CD = #{gvCmpnyCd}
  AND USER_CD  = #{userCd}

/* User01Mapper.cancelWithdrawal */
UPDATE TB_USER
SET WITHDRAWAL_DATE = null
    , UPDATE_NO     = #{gvUserCd}
	, UPDATE_DATE   = NOW()
WHERE
	CMPNY_CD = #{gvCmpnyCd}
AND USER_CD = #{userCd}

