mapper.update:
    /* User01Mapper.deleteUserSiteAuth */
    UPDATE TB_USER_SITE_AUTH
   	SET 
   		USE_YN = 'N'
   		, UPDATE_NO = #{gvUserCd}
  		, UPDATE_DATE = NOW()
	WHERE CMPNY_CD = #{cmpnyCd}
	  AND USER_CD = #{userCd}

    /* User01Mapper.insertUserSiteAuth */
    INSERT INTO TB_USER_SITE_AUTH (
    	CMPNY_CD
    	, USER_CD
    	, SITE_CD
    	, USE_YN
    	, INSERT_NO
    	, INSERT_DATE
    	, UPDATE_NO
    	, UPDATE_DATE
    )
    VALUES (
    	#{cmpnyCd}
    	, #{userCd}
    	, #{siteCd}
    	, IFNULL(#{useYn}, 'Y')
    	, #{gvUserCd}
    	, NOW()
    	, #{gvUserCd}
    	, NOW()
    ) AS NEW
    ON DUPLICATE KEY UPDATE
	    USE_YN        = NEW.USE_YN
	    , UPDATE_NO   = NEW.UPDATE_NO
	    , UPDATE_DATE = NEW.UPDATE_DATE

