/* User01Mapper.mergeUserInfo */
UPDATE TB_USER 
SET 
	SITE_CD = #{siteCd}
	, NODE_CD = #{nodeCd}
	, AUTH_CD = #{authCd}
	, RANK_CD = #{rankCd}
	, MBL_NO_ENC = #{mblNoEnc}
	, MBL_NO_HMAC = #{mblNoHmac}
	, EMAIL_ENC = #{emailEnc}
	, EMAIL_HMAC = #{emailHmac}
	, GENDER = #{gender}
	, BIRTH_DT_ENC = #{birthDtEnc}
	, USE_YN = IFNULL(#{useYn}, 'Y')
	, UPDATE_NO = #{gvUserCd}
	, UPDATE_DATE = NOW()
WHERE 1=1
  AND CMPNY_CD = #{cmpnyCd}
  AND USER_CD = #{userCd}

