INSERT INTO TB_USER_HIRE_DATE_HISTORY (
	HIST_ID
	, CMPNY_CD
	, USER_CD
	, PREV_HIRE_DATE
	, NEW_HIRE_DATE
	, CHANGE_REASON
	, HANDLING_TYPE
	, AFFECTED_GRANT_SNAPSHOT
	, OLD_GRANT_TOTAL
	, NEW_GRANT_TOTAL
	, WITHDRAW_REASON
	, INSERT_NO
	, INSERT_DATE
)
VALUES (
	#{histId}
	, #{cmpnyCd}
	, #{userCd}
	, #{prevHireDate}
	, #{newHireDate}
	, #{changeReason}
	, #{handlingType}
	, #{affectedGrantSnapshot}
	, #{oldGrantTotal}
	, #{newGrantTotal}
	, #{withdrawReason}
	, #{gvUserCd}
	, NOW()
)

mapper.select:
/* User01Mapper.selectUserStatutoryLeaveSummary */
SELECT
	COALESCE(SUM(A.GRANT_DAYS), 0) AS grantedSum
	, COALESCE(SUM(A.USED_DAYS), 0) AS usedSum
FROM TB_USER_LEAVE_GRANT A
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.USER_CD  = #{userCd}
  AND A.GRANT_TYPE LIKE 'STATUTORY\_%'
  AND A.STATUS IN ('ACTIVE', 'EXHAUSTED')
  AND A.DEL_YN = 'N'
